/* ---------- Océanie et Pacifique ---------- */
const D50 = [
{ id:'hangi', c:'oc', lat:-38.137, lon:176.251, base:12, prep:150, cook:210, diff:3, tags:['festive','slow','poultry'],
  art:{v:'board',bg:'#2b2419',plate:'#f0e4c8',style:'grill',food:['#8f5a3a','#c9754a','#e8dcb8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Hāngī',en:'Hāngī'},
  p:{fr:'Rotorua, Nouvelle-Zélande',en:'Rotorua, New Zealand'},
  d:{fr:"Viandes et légumes cuits dans un four de terre sur des pierres volcaniques chauffées à blanc, sous des sacs mouillés. À Rotorua, certaines familles utilisent directement la vapeur géothermique : la terre y cuit le repas toute seule.",
     en:"Meat and vegetables cooked in an earth oven on white-hot volcanic stones, under wet sacking. In Rotorua some families use geothermal steam directly: there the ground cooks the meal by itself."},
  i:[['pork_shoulder',2,'kg'],['chicken',2,'kg'],['lamb_leg',1.5,'kg'],['kumara',2,'kg'],['potato',2,'kg'],['pumpkin',1.5,'kg'],['cabbage',1,'pc'],['puha',500,'g'],['coarse_salt',4,'tbsp'],['pepper',null,'']],
  s:{fr:["Creusez un trou d'un mètre carré et de soixante centimètres de profondeur, et empilez-y des pierres volcaniques sur un feu de bois dur.","Laissez chauffer trois heures : les pierres doivent être grises de chaleur et non plus noires.","Retirez le bois, égalisez les pierres, et couvrez-les de feuilles vertes ou de linges mouillés pour empêcher la brûlure.","Rangez les paniers : viandes en bas, tubercules au milieu, légumes verts en haut. Arrosez d'un seau d'eau pour créer la vapeur.","Couvrez de sacs mouillés puis de terre, sans laisser fuir la vapeur, et laissez 3 heures. On déterre le hāngī en silence."],
     en:["Dig a pit a metre square and sixty centimetres deep, and stack volcanic stones on a hardwood fire in it.","Let them heat for three hours: the stones must be grey with heat and no longer black.","Rake out the wood, level the stones, and cover them with green leaves or wet cloths to prevent scorching.","Stack the baskets: meat at the bottom, roots in the middle, greens on top. Throw on a bucket of water to raise the steam.","Cover with wet sacking then earth, letting no steam escape, and leave for 3 hours. The hāngī is unearthed in silence."]} },

{ id:'boil-up', c:'oc', lat:-41.289, lon:174.777, base:6, prep:25, cook:120, diff:1, tags:['pork','soup','comfort'],
  art:{v:'pot',bg:'#28331f',plate:'#f0e4c8',style:'soup',food:['#4f6f3a','#e8dcb8','#c9924a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Boil-up',en:'Boil-up'},
  p:{fr:'Wellington, Nouvelle-Zélande',en:'Wellington, New Zealand'},
  d:{fr:"Un bouillon d'os de porc fumé, de pūhā sauvage et de kūmara, avec des dumplings appelés doughboys. C'est le plat du quotidien maori, celui qu'on fait quand la marmite doit nourrir tout le monde sans prévenir.",
     en:"A broth of smoked pork bones, wild pūhā and kūmara, with dumplings called doughboys. It is the everyday Māori dish, made when the pot must feed everyone without warning."},
  i:[['pork_bones',1.5,'kg'],['puha',600,'g'],['watercress',400,'g'],['kumara',800,'g'],['potato',600,'g'],['pumpkin',500,'g'],['flour',300,'g'],['baking_powder',2,'tsp'],['butter',40,'g'],['whole_milk',150,'ml'],['onion',2,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites blanchir les os fumés 10 minutes et jetez cette première eau, très salée.","Remettez-les dans trois litres d'eau claire avec l'oignon et laissez frémir 1 heure.","Lavez le pūhā plusieurs fois et frottez-le entre les mains jusqu'à ce que le suc laiteux s'échappe : c'est ce qui ôte l'amertume.","Ajoutez les tubercules en gros morceaux et laissez cuire 25 minutes.","Formez les doughboys avec farine, levure, beurre et lait, déposez-les sur le bouillon, couvrez et laissez gonfler 15 minutes. Ajoutez le pūhā en dernier."],
     en:["Blanch the smoked bones for 10 minutes and throw away that first, very salty water.","Return them to three litres of clean water with the onion and simmer for 1 hour.","Wash the pūhā several times and rub it between your hands until the milky sap runs: this is what removes the bitterness.","Add the roots in large pieces and cook for 25 minutes.","Make the doughboys from flour, baking powder, butter and milk, drop them on the broth, cover and let them swell for 15 minutes. Add the pūhā last."]} },

{ id:'damper-au-feu', c:'oc', lat:-23.698, lon:133.881, base:8, prep:20, cook:45, diff:1, tags:['bread','bake','comfort'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#c9a878','#e8dcb8','#8f6a4a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Damper',en:'Damper'},
  p:{fr:'Alice Springs, Territoire du Nord, Australie',en:'Alice Springs, Northern Territory, Australia'},
  d:{fr:"Un pain sans levure cuit sous la cendre, inventé par les bouviers du bush qui n'avaient ni four ni levure. On le rompt à la main et on le mange avec du golden syrup, jamais coupé au couteau.",
     en:"An unleavened bread baked under ash, invented by bush drovers who had neither oven nor yeast. It is broken by hand and eaten with golden syrup, never cut with a knife."},
  i:[['flour',600,'g'],['baking_powder',3,'tsp'],['butter',80,'g'],['whole_milk',350,'ml'],['golden_syrup',150,'ml'],['salt',null,'']],
  s:{fr:["Faites un feu de bois dur et laissez-le retomber en braises épaisses : il faut de la cendre chaude, pas de flamme.","Mêlez farine, levure et sel, puis sablez le beurre froid du bout des doigts.","Versez le lait d'un coup et rassemblez la pâte en quelques gestes seulement : trop pétrie, elle devient dure comme une pierre.","Formez une boule aplatie, entaillez une croix sur le dessus et farinez-la généreusement.","Enfouissez-la sous la cendre chaude 40 minutes, ou cuisez 35 minutes à 200 °C. Le pain sonne creux quand il est prêt."],
     en:["Build a hardwood fire and let it fall to thick embers: you need hot ash, not flame.","Mix the flour, baking powder and salt, then rub in the cold butter with your fingertips.","Pour in the milk all at once and bring the dough together in a few movements only: overworked, it bakes hard as a stone.","Shape a flattened round, cut a cross in the top and flour it generously.","Bury it under hot ash for 40 minutes, or bake for 35 minutes at 200°C. The loaf sounds hollow when it is done."]} },

{ id:'vakalolo', c:'oc', lat:-17.798, lon:177.421, base:8, prep:40, cook:60, diff:2, tags:['sweet','festive','comfort'],
  art:{v:'leaf',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#c9924a','#e0b45a','#f4f0e6','#8f6a4a'],garnish:'#c9754a'},
  n:{fr:'Vakalolo',en:'Vakalolo'},
  p:{fr:'Nadi, Viti Levu, Fidji',en:'Nadi, Viti Levu, Fiji'},
  d:{fr:"Un gâteau de manioc râpé cuit en feuille, nappé d'un caramel de lait de coco et de sucre de canne. On le partage au lovo, le four de terre fidjien, et la part revient d'abord aux anciens du village.",
     en:"A cake of grated cassava cooked in leaves, coated with a caramel of coconut milk and cane sugar. It is shared at the lovo, the Fijian earth oven, and the first portion goes to the village elders."},
  i:[['cassava',1.2,'kg'],['coconut_cream',500,'ml'],['brown_sugar',300,'g'],['banana_leaf',10,'pc'],['coconut',150,'g'],['vanilla',1,'pc'],['salt',null,'']],
  s:{fr:["Râpez le manioc épluché sur une râpe fine et pressez-en une partie du jus : trop humide, le gâteau ne prend pas.","Mêlez-le à la moitié de la crème de coco, à un tiers du sucre et à une pincée de sel.","Étalez la pâte sur 3 cm sur des feuilles de bananier assouplies à la flamme, et refermez en paquet plat.","Cuisez 50 minutes à la vapeur ou dans le lovo, jusqu'à ce que la pâte devienne translucide.","Faites un caramel avec le reste du sucre, versez la crème de coco restante hors du feu et nappez-en le gâteau tiède."],
     en:["Grate the peeled cassava finely and squeeze out some of the juice: too wet, the cake will not set.","Mix it with half the coconut cream, a third of the sugar and a pinch of salt.","Spread the paste 3 cm thick on banana leaves softened over a flame, and fold into a flat parcel.","Cook for 50 minutes by steaming or in the lovo, until the paste turns translucent.","Make a caramel with the remaining sugar, pour in the rest of the coconut cream off the heat and coat the warm cake with it."]} },

{ id:'panipopo', c:'oc', lat:-13.850, lon:-171.751, base:8, prep:120, cook:35, diff:2, tags:['sweet','bake','breakfast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#f4f0e6','#e0b45a','#f2dfa8','#c9924a'],garnish:'#c9754a'},
  n:{fr:'Panipopo',en:'Panipopo'},
  p:{fr:'Apia, Samoa',en:'Apia, Samoa'},
  d:{fr:"Des petits pains levés cuits dans une sauce au lait de coco qui caramélise autour d'eux. Pani vient de l'anglais bun, popo veut dire noix de coco : le nom raconte à lui seul l'histoire du Pacifique.",
     en:"Yeasted buns baked in a coconut milk sauce that caramelises around them. Pani comes from English 'bun', popo means coconut: the name alone tells the history of the Pacific."},
  i:[['flour',600,'g'],['dry_yeast',10,'g'],['sugar',150,'g'],['whole_milk',250,'ml'],['butter',80,'g'],['egg',1,'pc'],['coconut_milk',600,'ml'],['cornstarch',1,'tbsp'],['salt',null,'']],
  s:{fr:["Délayez la levure et une cuillerée de sucre dans le lait tiède, laissez mousser dix minutes.","Pétrissez avec la farine, le beurre fondu, l'œuf, 50 g de sucre et le sel, 10 minutes, puis laissez lever 1 heure.","Formez des boules de 60 g et rangez-les serrées dans un plat beurré, sans les coller tout à fait.","Laissez pousser 40 minutes, puis versez tout autour le lait de coco battu avec le reste du sucre et la fécule.","Enfournez 30 minutes à 190 °C : les pains gonflent en absorbant la sauce, qui caramélise au fond."],
     en:["Dissolve the yeast and a spoonful of sugar in the warm milk, and let it froth for ten minutes.","Knead with the flour, melted butter, egg, 50 g of sugar and the salt for 10 minutes, then prove for 1 hour.","Shape 60 g balls and set them close together in a buttered dish, without quite touching.","Let them rise for 40 minutes, then pour round the coconut milk whisked with the remaining sugar and the cornstarch.","Bake for 30 minutes at 190°C: the buns swell as they drink the sauce, which caramelises underneath."]} },

{ id:'ota-ika', c:'oc', lat:-21.139, lon:-175.202, base:4, prep:30, cook:0, diff:1, tags:['sea','fresh','raw'],
  art:{v:'bowl',bg:'#26384a',plate:'#f4f0e6',style:'salad',food:['#f4f0e6','#c9402c','#7fae5a','#f0a878'],garnish:'#6fbf8f'},
  n:{fr:'ʻOta ʻika',en:'ʻOta ʻika'},
  p:{fr:'Nukuʻalofa, Tonga',en:'Nukuʻalofa, Tonga'},
  d:{fr:"Le cousin tongien du kokoda, plus sec et plus poivré, où le poisson ne trempe que quelques minutes. À Tonga, on le prépare le dimanche après l'office, sur la plage, avec le poisson pêché la veille.",
     en:"The Tongan cousin of kokoda, drier and more peppery, where the fish steeps only a few minutes. In Tonga it is made on Sunday after church, on the beach, with fish caught the day before."},
  i:[['tuna',700,'g'],['lime',8,'pc'],['coconut_cream',300,'ml'],['red_onion',1,'pc'],['ripe_tomato',250,'g'],['spring_onion',4,'pc'],['bird_eye_chili',2,'pc'],['cucumber',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Taillez le thon très frais en cubes réguliers et gardez-le sur la glace jusqu'au dernier moment.","Salez-le et versez le jus de citron vert : laissez seulement dix minutes, la chair doit rester rouge à cœur.","Égouttez sans presser et jetez le jus.","Ajoutez la crème de coco, l'oignon rouge en fines lamelles, la tomate, le concombre et le piment.","Poivrez généreusement et servez aussitôt, avant que le sel ne fasse rendre l'eau aux légumes."],
     en:["Cut very fresh tuna into even cubes and keep it on ice until the last moment.","Salt it and pour over the lime juice: leave only ten minutes, the flesh must stay red at the centre.","Drain without pressing and discard the juice.","Add the coconut cream, thinly sliced red onion, tomato, cucumber and chilli.","Season generously with pepper and serve at once, before the salt draws water from the vegetables."]} },

{ id:'saksak', c:'oc', lat:-4.207, lon:152.163, base:8, prep:40, cook:45, diff:2, tags:['sweet','comfort','fresh'],
  art:{v:'leaf',bg:'#33291f',plate:'#f4f0e6',style:'cake',food:['#f4f0e6','#e8c46a','#c9924a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Saksak',en:'Saksak'},
  p:{fr:'Rabaul, Nouvelle-Bretagne, Papouasie-Nouvelle-Guinée',en:'Rabaul, New Britain, Papua New Guinea'},
  d:{fr:"Un pudding d'amidon de sagou et de banane cuit dans la crème de coco, translucide et élastique. Le sagou vient du cœur d'un palmier abattu : un seul arbre nourrit une famille pendant des mois.",
     en:"A pudding of sago starch and banana cooked in coconut cream, translucent and elastic. Sago comes from the heart of a felled palm: one tree feeds a family for months."},
  i:[['sago_starch',400,'g'],['ripe_banana',8,'pc'],['coconut_cream',700,'ml'],['brown_sugar',120,'g'],['banana_leaf',8,'pc'],['salt',null,'']],
  s:{fr:["Délayez l'amidon de sagou dans l'eau froide et laissez-le décanter, puis jetez l'eau claire du dessus.","Écrasez les bananes très mûres à la fourchette et mêlez-les à la pâte de sagou.","Faites chauffer la crème de coco avec le sucre et une pincée de sel, sans la faire bouillir.","Versez-y le mélange en remuant sans arrêt : la pâte devient translucide et se met à filer en quelques minutes.","Versez sur des feuilles de bananier, roulez en boudin, liez et laissez raffermir une heure avant de trancher."],
     en:["Slake the sago starch in cold water and let it settle, then pour off the clear water on top.","Mash the very ripe bananas with a fork and combine them with the sago paste.","Heat the coconut cream with the sugar and a pinch of salt, without letting it boil.","Pour in the mixture, stirring constantly: the paste turns translucent and starts to stretch within minutes.","Turn it out onto banana leaves, roll into a log, tie it and let it firm for an hour before slicing."]} },

{ id:'simboro', c:'oc', lat:-15.512, lon:167.180, base:6, prep:70, cook:60, diff:2, tags:['veg','comfort','slow'],
  art:{v:'leaf',bg:'#28331f',plate:'#f4ecd8',style:'cake',food:['#4f6f3a','#e8dcb8','#f4f0e6','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Simboro',en:'Simboro'},
  p:{fr:'Luganville, Espiritu Santo, Vanuatu',en:'Luganville, Espiritu Santo, Vanuatu'},
  d:{fr:"Des rouleaux de manioc râpé enveloppés dans des feuilles d'island cabbage et pochés dans le lait de coco. C'est le laplap du jour ordinaire : plus rapide, sans four de terre, mais toujours râpé à la pierre.",
     en:"Rolls of grated cassava wrapped in island cabbage leaves and poached in coconut milk. It is the everyday laplap: quicker, without an earth oven, but still grated on stone."},
  i:[['cassava',1.2,'kg'],['island_cabbage',600,'g'],['coconut_milk',800,'ml'],['onion',2,'pc'],['spring_onion',5,'pc'],['coconut_cream',200,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Râpez le manioc épluché très finement et pressez-en une partie du jus, sans le dessécher.","Salez la pâte et façonnez des boudins de la taille d'un doigt, entre les paumes mouillées.","Enveloppez chacun dans deux ou trois feuilles d'island cabbage, en serrant bien, et liez d'une lanière de feuille.","Rangez-les serrés dans une marmite et couvrez de lait de coco allongé d'un peu d'eau.","Laissez pocher 50 minutes à feu doux sans bouillir, puis nappez de crème de coco et d'oignon vert."],
     en:["Grate the peeled cassava very finely and squeeze out some of its juice, without drying it out.","Salt the paste and shape finger-sized rolls between wet palms.","Wrap each in two or three island cabbage leaves, pulled tight, and tie with a strip of leaf.","Pack them closely in a pot and cover with coconut milk let down with a little water.","Poach for 50 minutes over low heat without boiling, then finish with coconut cream and spring onion."]} },

{ id:'ika-mata-rarotonga', c:'oc', lat:-21.229, lon:-159.777, base:4, prep:25, cook:0, diff:1, tags:['sea','fresh','fast'],
  art:{v:'bowl',bg:'#26384a',plate:'#f4f0e6',style:'salad',food:['#f4f0e6','#e0703a','#7fae5a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Ika mata',en:'Ika mata'},
  p:{fr:'Rarotonga, îles Cook',en:'Rarotonga, Cook Islands'},
  d:{fr:"Du thon cru au lait de coco et au citron vert, avec très peu de choses autour : oignon vert, concombre et sel. La retenue est la règle aux Cook — on veut goûter le poisson, pas la garniture.",
     en:"Raw tuna with coconut milk and lime, and very little else: spring onion, cucumber and salt. Restraint is the rule in the Cooks — you are meant to taste the fish, not the garnish."},
  i:[['tuna',600,'g'],['lime',6,'pc'],['coconut_milk',350,'ml'],['spring_onion',5,'pc'],['cucumber',1,'pc'],['ripe_tomato',200,'g'],['bird_eye_chili',1,'pc'],['salt',null,'']],
  s:{fr:["Taillez le thon en dés de 1,5 cm, en écartant les parties nerveuses.","Mêlez-le au sel et au jus de citron vert et laissez 15 minutes, pas davantage.","Égouttez soigneusement : le poisson doit rester rosé au centre.","Ajoutez le lait de coco frais, l'oignon vert émincé, le concombre en dés et la tomate.","Servez immédiatement, dans des bols très froids ou des demi-noix de coco."],
     en:["Cut the tuna into 1.5 cm dice, discarding sinewy parts.","Toss it with salt and lime juice and leave 15 minutes, no longer.","Drain thoroughly: the fish should stay pink at the centre.","Add the fresh coconut milk, sliced spring onion, diced cucumber and tomato.","Serve immediately, in very cold bowls or half coconut shells."]} },

{ id:'poe-banane', c:'oc', lat:-17.535, lon:-149.570, base:8, prep:30, cook:60, diff:1, tags:['sweet','fresh','comfort'],
  art:{v:'bowl',bg:'#28331f',plate:'#f4f0e6',style:'cake',food:['#e8c46a','#f4f0e6','#c9924a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Po’e à la banane',en:'Banana poʻe'},
  p:{fr:'Papeete, Tahiti, Polynésie française',en:'Papeete, Tahiti, French Polynesia'},
  d:{fr:"Un flan épais de banane écrasée et d'amidon de manioc, cuit au four et noyé de lait de coco frais. On le servait cuit sous la terre, dans le ahima'a ; le four moderne l'a raccourci sans le trahir.",
     en:"A dense pudding of mashed banana and cassava starch, baked and drowned in fresh coconut milk. It was once cooked underground in the ahimaʻa; the modern oven shortened it without betraying it."},
  i:[['ripe_banana',10,'pc'],['cassava_starch',250,'g'],['sugar',150,'g'],['vanilla',2,'pc'],['coconut_milk',600,'ml'],['butter',60,'g'],['lime',1,'pc'],['salt',null,'']],
  s:{fr:["Choisissez des bananes très mûres, presque noires : c'est d'elles que vient tout le sucre du plat.","Écrasez-les à la fourchette, jamais au mixeur, pour garder des morceaux.","Mêlez-les à l'amidon de manioc, au sucre, à la vanille grattée et au zeste de citron vert.","Versez dans un plat beurré sur 4 cm et enfournez 50 minutes à 180 °C : le dessus doit brunir et le cœur rester tremblant.","Laissez tiédir, coupez en carrés et servez noyé de lait de coco frais, jamais chauffé."],
     en:["Choose very ripe, almost black bananas: all the sweetness of the dish comes from them.","Mash them with a fork, never in a blender, to keep some texture.","Mix them with the cassava starch, sugar, scraped vanilla and lime zest.","Pour into a buttered dish 4 cm deep and bake for 50 minutes at 180°C: the top should brown and the centre stay wobbly.","Let it cool, cut into squares and serve drowned in fresh coconut milk, never heated."]} }
,

{ id:'sausage-roll', c:'oc', lat:-33.868, lon:151.209, base:8, prep:60, cook:35, diff:2, tags:['pork','bake','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e8c46a','#f2dfa8','#8f5a3a','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Sausage roll',en:'Sausage roll'},
  p:{fr:'Sydney, Nouvelle-Galles du Sud, Australie',en:'Sydney, New South Wales, Australia'},
  d:{fr:"Un boudin de chair à saucisse enroulé dans une pâte feuilletée et cuit au four. C'est le pilier des boulangeries et des cantines scolaires australiennes ; on en consomme plus par habitant qu'au Royaume-Uni dont il est pourtant originaire.",
     en:"A log of sausage meat rolled in puff pastry and baked. It is the mainstay of Australian bakeries and school canteens; more are eaten per head here than in the United Kingdom it came from."},
  i:[['puff_pastry',500,'g'],['ground_pork',600,'g'],['breadcrumbs',80,'g'],['onion',1,'pc'],['egg',2,'pc'],['sage',5,'g'],['nutmeg',3,'g'],['worcestershire',20,'ml'],['ketchup',100,'g'],['pepper',null,''],['salt',null,'']],
  s:{fr:["Faites suer l'oignon très finement haché et laissez-le refroidir avant de l'ajouter à la viande.","Un oignon cru rend son eau à la cuisson et détrempe la pâte par en dessous — c'est le défaut le plus fréquent.","Mêlez la chair, la chapelure et les aromates, et faites cuire une cuillerée à la poêle pour goûter l'assaisonnement.","Formez un boudin régulier sur le bord de la pâte, roulez et scellez sous le rouleau, la soudure vers le bas.","Dorez à l'œuf, incisez trois fois et cuisez 35 minutes à 200 °C. Servez avec du ketchup, jamais autre chose."],
     en:["Sweat the very finely chopped onion and cool it before adding it to the meat.","Raw onion releases water as it cooks and soaks the pastry from below — the commonest fault.","Mix the meat, breadcrumbs and seasonings, and fry a spoonful to taste for seasoning.","Shape an even log along the edge of the pastry, roll and seal under the roll, seam down.","Glaze with egg, cut three vents and bake 35 minutes at 200°C. Serve with tomato sauce, never anything else."]} },

{ id:'barramundi-grille', c:'oc', lat:-33.870, lon:151.191, base:4, prep:30, cook:20, diff:2, tags:['sea','grill','fresh'],
  art:{v:'plate',bg:'#26485c',plate:'#f0e4c8',style:'fish',food:['#f4f0e6','#e8c46a','#7fae5a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Barramundi grillé',en:'Grilled barramundi'},
  p:{fr:'Sydney Fish Market, Australie',en:'Sydney Fish Market, Australia'},
  d:{fr:"Un filet de barramundi grillé peau croustillante, au citron et aux herbes. Le nom vient d'une langue aborigène du Queensland et signifie « poisson à grandes écailles » ; l'espèce change de sexe en vieillissant, tous les individus naissant mâles.",
     en:"A barramundi fillet grilled with crisp skin, with lemon and herbs. The name comes from a Queensland Aboriginal language and means large-scaled fish; the species changes sex with age, every individual being born male."},
  i:[['barramundi',800,'g'],['lemon',2,'pc'],['butter',80,'g'],['garlic',4,'clove'],['parsley',1,'bunch'],['olive_oil',60,'ml'],['potato',600,'g'],['green_beans',300,'g'],['pepper',null,''],['salt',null,'']],
  s:{fr:["Séchez la peau à fond au papier absorbant et salez-la vingt minutes avant, à découvert.","Ce salage tire l'humidité vers la surface, où elle s'évapore : sans lui, la peau colle et ne croustille jamais.","Incisez la peau trois fois sans atteindre la chair, pour éviter que le filet ne se courbe.","Posez côté peau dans une poêle chaude et pressez dix secondes avec une spatule, puis n'y touchez plus, quatre minutes.","Retournez une minute seulement, ajoutez le beurre, l'ail et le citron, et arrosez hors du feu."],
     en:["Dry the skin thoroughly with paper and salt it twenty minutes ahead, uncovered.","That salting draws moisture to the surface where it evaporates: without it the skin sticks and never crisps.","Score the skin three times without reaching the flesh, to stop the fillet curling.","Lay it skin down in a hot pan and press ten seconds with a spatula, then leave it alone for four minutes.","Turn for one minute only, add the butter, garlic and lemon, and baste off the heat."]} },

{ id:'chicken-parmigiana', c:'oc', lat:-33.873, lon:151.207, base:4, prep:40, cook:35, diff:2, tags:['poultry','fry','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f0e4c8',style:'other',food:['#c9302a','#f4f0e6','#c9924a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Chicken parmigiana',en:'Chicken parmigiana'},
  p:{fr:'Sydney, Nouvelle-Galles du Sud, Australie',en:'Sydney, New South Wales, Australia'},
  d:{fr:"Une escalope panée couverte de sauce tomate, de jambon et de fromage fondu. La parma est le plat de pub australien par excellence, malgré son nom italien : elle descend de la parmigiana d'aubergines, où le poulet a remplacé le légume en passant par l'Amérique.",
     en:"A crumbed escalope covered with tomato sauce, ham and melted cheese. The parma is the Australian pub dish par excellence, despite the Italian name: it descends from aubergine parmigiana, with chicken replacing the vegetable by way of America."},
  i:[['chicken_breast',4,'pc'],['flour',100,'g'],['egg',3,'pc'],['breadcrumbs',250,'g'],['ripe_tomato',600,'g'],['mozzarella',250,'g'],['parmesan',80,'g'],['ham',150,'g'],['garlic',5,'clove'],['oregano',5,'g'],['frying_oil',500,'ml'],['potato',800,'g'],['salt',null,'']],
  s:{fr:["Ouvrez les blancs en portefeuille et aplatissez-les au maillet jusqu'à un centimètre d'épaisseur uniforme.","Panez à l'anglaise en pressant fermement, puis laissez reposer vingt minutes au frais pour que la panure adhère.","Faites d'abord frire l'escalope à la poêle, jusqu'à ce qu'elle soit dorée et cuite, avant de la garnir.","Garnie crue puis passée au four, la panure ramollit sous la sauce et le plat perd tout son croquant.","Ajoutez sauce, jambon et fromage et passez sous le gril cinq minutes seulement. Servez avec des frites et une salade."],
     en:["Butterfly the breasts and flatten them with a mallet to an even centimetre.","Crumb them in the standard way, pressing firmly, then rest twenty minutes in the cold so the coating adheres.","Fry the escalope in a pan first, until golden and cooked, before topping it.","Topped raw then baked, the crumb goes soft under the sauce and the dish loses all its crunch.","Add sauce, ham and cheese and grill for five minutes only. Serve with chips and a salad."]} },

{ id:'sausage-sizzle', c:'oc', lat:-33.860, lon:151.150, base:8, prep:20, cook:25, diff:1, tags:['grill','street','fast'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#8f5a3a','#f2dfa8','#e8c46a','#c9302a'],garnish:'#7fae6a'},
  n:{fr:'Sausage sizzle',en:'Sausage sizzle'},
  p:{fr:'Sydney, Nouvelle-Galles du Sud, Australie',en:'Sydney, New South Wales, Australia'},
  d:{fr:"Une saucisse grillée posée en diagonale sur une tranche de pain de mie, avec oignon et sauce tomate. On le vend devant les magasins de bricolage et les bureaux de vote ; le jour d'une élection fédérale, on parle de democracy sausage, et une carte nationale en recense les stands.",
     en:"A grilled sausage laid diagonally on a slice of white bread, with onion and tomato sauce. It is sold outside hardware stores and polling places; on federal election day it is the democracy sausage, and a national map tracks the stalls."},
  i:[['beef_sausage',8,'pc'],['white_bread',8,'pc'],['onion',4,'pc'],['ketchup',150,'g'],['mustard',60,'g'],['butter',80,'g'],['sunflower_oil',40,'ml']],
  s:{fr:["Faites cuire les oignons émincés en premier, longuement et à feu doux, jusqu'à ce qu'ils soient franchement bruns et sucrés.","Poussez-les sur le bord de la plaque : ils continuent de confire dans le gras des saucisses pendant toute la cuisson.","Grillez les saucisses vingt minutes à feu moyen en les tournant souvent — à feu vif la peau éclate et le jus se perd.","Ne les piquez jamais : c'est la faute que tout le monde commet et qui donne une saucisse sèche.","Posez la saucisse en diagonale sur le pain beurré, ajoutez l'oignon, la sauce, et repliez les coins. Se mange debout."],
     en:["Cook the sliced onions first, at length over low heat, until frankly brown and sweet.","Push them to the edge of the plate: they go on confiting in the sausage fat throughout.","Grill the sausages twenty minutes over medium heat, turning often — over high heat the skin bursts and the juice is lost.","Never prick them: it is the mistake everyone makes and it gives a dry sausage.","Lay the sausage diagonally on the buttered bread, add onion and sauce, and fold the corners in. Eaten standing."]} },

{ id:'burger-with-the-lot', c:'oc', lat:-33.880, lon:151.215, base:4, prep:40, cook:30, diff:2, tags:['beef','street','comfort'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#8f4a3a','#e8c46a','#c9302a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Burger with the lot',en:'Burger with the lot'},
  p:{fr:'Sydney, Nouvelle-Galles du Sud, Australie',en:'Sydney, New South Wales, Australia'},
  d:{fr:"Un hamburger australien empilant bœuf, bacon, œuf, betterave et ananas. La tranche de betterave au vinaigre est la signature nationale : elle n'existe nulle part ailleurs, et son absence suffit à disqualifier un burger aux yeux d'un Australien.",
     en:"An Australian hamburger stacking beef, bacon, egg, beetroot and pineapple. The slice of pickled beetroot is the national signature: it exists nowhere else, and its absence alone disqualifies a burger in Australian eyes."},
  i:[['ground_beef',600,'g'],['bread_roll',4,'pc'],['smoked_bacon',8,'pc'],['egg',4,'pc'],['pickled_beets',150,'g'],['pineapple',4,'slice'],['cheddar_cheese',150,'g'],['onion',2,'pc'],['lettuce',8,'pc'],['ripe_tomato',2,'pc'],['ketchup',80,'g'],['butter',60,'g'],['salt',null,'']],
  s:{fr:["Formez des steaks larges et plats, plus larges que le pain : ils se rétractent d'un bon centimètre à la cuisson.","Creusez le centre au pouce, ce qui empêche le steak de gonfler en dôme.","Égouttez soigneusement la betterave et l'ananas sur du papier avant de les poser.","Le jus de betterave traverse le pain en deux minutes ; c'est là que tout se joue.","Empilez dans l'ordre : pain, salade, steak, fromage, bacon, œuf, betterave, ananas, sauce. La salade en bas protège le pain."],
     en:["Shape wide, flat patties, wider than the bun: they shrink a good centimetre as they cook.","Press a dimple in the centre with your thumb, which stops the patty doming.","Drain the beetroot and pineapple thoroughly on paper before laying them on.","Beetroot juice goes through the bun in two minutes; that is where it is won or lost.","Stack in order: bun, lettuce, patty, cheese, bacon, egg, beetroot, pineapple, sauce. The lettuce underneath protects the bread."]} },

{ id:'salt-pepper-squid', c:'oc', lat:-33.865, lon:151.196, base:4, prep:40, cook:15, diff:2, tags:['sea','fry','fast'],
  art:{v:'board',bg:'#26485c',plate:'#f4ead4',style:'other',food:['#f2dfa8','#e8c46a','#f4f0e6','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Salt and pepper squid',en:'Salt and pepper squid'},
  p:{fr:'Sydney, Nouvelle-Galles du Sud, Australie',en:'Sydney, New South Wales, Australia'},
  d:{fr:"Des calmars frits à la fécule, relevés au poivre du Sichuan et au piment. Le plat est arrivé avec les Cantonais des champs aurifères du XIXe siècle et s'est si bien installé qu'on le trouve dans tous les pubs, sans que personne y voie un plat chinois.",
     en:"Squid fried in starch, seasoned with Sichuan pepper and chilli. It came with the Cantonese of the nineteenth-century goldfields and settled so thoroughly that every pub serves it, without anyone thinking of it as Chinese."},
  i:[['squid',800,'g'],['cornstarch',200,'g'],['sichuan_peppercorns',15,'g'],['black_peppercorns',10,'g'],['chili_pepper',2,'pc'],['garlic',6,'clove'],['scallion',1,'bunch'],['frying_oil',1.5,'l'],['lemon',2,'pc'],['coarse_salt',20,'g'],['mayonnaise',150,'g']],
  s:{fr:["Fendez les corps de calmar, retournez-les et incisez la face interne en croisillons sans traverser.","Coupez en carrés : les entailles font que les morceaux se roulent en cuisant, et la chair reste tendre.","Grillez à sec les poivres du Sichuan et noir, puis moulez-les avec le gros sel — jamais l'inverse, le sel humide colle au moulin.","Enrobez le calmar sec de fécule seule, en secouant l'excédent, et frites à 190 °C.","Quatre-vingt-dix secondes, pas davantage. Au-delà de deux minutes le calmar devient caoutchouteux et rien ne le rattrape."],
     en:["Split the squid tubes, open them out and score the inner face in a lattice without cutting through.","Cut into squares: the scoring makes the pieces curl as they cook, and the flesh stays tender.","Dry-toast the Sichuan and black peppercorns, then grind them with the coarse salt — never the reverse, damp salt clogs the mill.","Coat the dry squid in starch alone, shaking off the excess, and fry at 190°C.","Ninety seconds, no more. Beyond two minutes squid turns rubbery and nothing recovers it."]} },

{ id:'caramel-slice', c:'oc', lat:-33.876, lon:151.204, base:12, prep:60, cook:40, diff:2, tags:['sweet','bake','comfort'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#3a2018','#c9754a','#f2dfa8','#e8c46a'],garnish:'#c9754a'},
  n:{fr:'Caramel slice',en:'Caramel slice'},
  p:{fr:'Sydney, Nouvelle-Galles du Sud, Australie',en:'Sydney, New South Wales, Australia'},
  d:{fr:"Trois couches : un sablé à la noix de coco, un caramel au lait concentré, une ganache de chocolat. Il n'existe aucune fête d'école, aucun café ni aucune boulangerie australienne sans lui ; on l'appelle aussi millionaire's shortbread ailleurs.",
     en:"Three layers: a coconut shortbread, a condensed milk caramel, a chocolate top. No Australian school fête, café or bakery is without it; elsewhere it goes by millionaire's shortbread."},
  i:[['flour',200,'g'],['coconut',80,'g'],['brown_sugar',100,'g'],['butter',300,'g'],['condensed_milk',800,'g'],['golden_syrup',80,'g'],['dark_chocolate',300,'g'],['sunflower_oil',20,'ml']],
  s:{fr:["Mêlez farine, coco, sucre brun et beurre fondu, tassez fermement dans le moule et cuisez 20 minutes à 180 °C.","Faites cuire le caramel à feu doux en remuant sans arrêt quinze minutes : il doit épaissir et brunir légèrement.","Remuez sans interruption : le lait concentré attache instantanément et un fond brûlé traverse tout le gâteau.","Versez sur le sablé encore tiède et repassez au four dix minutes, ce qui fixe le caramel et l'empêche de couler.","Laissez refroidir complètement avant le chocolat, additionné d'une cuillerée d'huile pour qu'il se coupe sans se briser."],
     en:["Mix flour, coconut, brown sugar and melted butter, press firmly into the tin and bake 20 minutes at 180°C.","Cook the caramel over low heat, stirring without pause for fifteen minutes: it should thicken and colour slightly.","Stir without stopping: condensed milk catches instantly and a burnt base carries through the whole slice.","Pour it over the still-warm base and return to the oven ten minutes, which sets the caramel and stops it running.","Cool completely before the chocolate, with a spoonful of oil added so it cuts without shattering."]} },

{ id:'dim-sim', c:'oc', lat:-37.831, lon:144.960, base:8, prep:90, cook:25, diff:2, tags:['pork','street','fry'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8c46a','#c9924a','#f2dfa8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Dim sim',en:'Dim sim'},
  p:{fr:'South Melbourne Market, Australie',en:'South Melbourne Market, Australia'},
  d:{fr:"Une grosse bouchée de porc et de chou, cuite à la vapeur ou frite, propre à l'Australie. Ce n'est pas un dim sum : elle a été créée à Melbourne dans les années 1940 par un cuisinier cantonais pour un public australien, et elle est trois fois plus grosse que son modèle.",
     en:"A large parcel of pork and cabbage, steamed or fried, peculiar to Australia. It is not dim sum: it was created in Melbourne in the 1940s by a Cantonese cook for an Australian public, and it is three times the size of its model."},
  i:[['ground_pork',600,'g'],['cabbage',400,'g'],['wonton_wrapper',30,'pc'],['scallion',1,'bunch'],['ginger',30,'g'],['soy_sauce',50,'ml'],['sesame_oil',20,'ml'],['cornstarch',30,'g'],['frying_oil',1.5,'l'],['garlic',4,'clove'],['salt',null,'']],
  s:{fr:["Hachez le chou très fin, salez-le vingt minutes et pressez-le à fond entre les mains.","Sans ce dégorgeage, l'eau du chou détrempe la farce et le dim sim s'affaisse à la cuisson.","Travaillez le porc en une seule direction jusqu'à ce qu'il devienne collant, puis incorporez le chou et la fécule.","Formez de grosses boules, deux fois plus grosses qu'un dim sum, et enveloppez sans plisser — la pâte se ferme simplement en bourse.","Cuisez douze minutes à la vapeur, puis frites une minute à 190 °C si vous les voulez croustillantes."],
     en:["Chop the cabbage very finely, salt it twenty minutes and press it out thoroughly between your hands.","Without that purging, the cabbage water soaks the filling and the dim sim collapses as it cooks.","Work the pork in one direction until it turns tacky, then fold in the cabbage and starch.","Form large balls, twice the size of a dim sum, and wrap without pleating — the wrapper simply gathers into a purse.","Steam twelve minutes, then fry one minute at 190°C if you want them crisp."]} },

{ id:'chiko-roll', c:'oc', lat:-36.758, lon:144.278, base:8, prep:90, cook:25, diff:3, tags:['street','fry','beef'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#c9924a','#e8c46a','#8f5a3a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Chiko roll',en:'Chiko roll'},
  p:{fr:'Bendigo, Victoria, Australie',en:'Bendigo, Victoria, Australia'},
  d:{fr:"Un gros rouleau frit à la pâte épaisse, garni de mouton, de chou et d'orge. Il a été conçu en 1951 pour être mangé d'une main dans les tribunes de football : la pâte est délibérément épaisse et résistante, précisément pour qu'il ne se déchire pas.",
     en:"A large fried roll in thick pastry, filled with mutton, cabbage and barley. It was designed in 1951 to be eaten one-handed in football stands: the pastry is deliberately thick and tough, precisely so it will not tear."},
  i:[['mutton_shoulder',400,'g'],['cabbage',500,'g'],['barley',150,'g'],['carrot',2,'pc'],['celery',3,'stalk'],['onion',2,'pc'],['flour',400,'g'],['cornstarch',100,'g'],['water',250,'ml'],['beef_stock',300,'ml'],['frying_oil',2,'l'],['pepper',null,''],['salt',null,'']],
  s:{fr:["Faites cuire l'orge trente minutes, hachez le mouton et les légumes très fin, et mijotez le tout jusqu'à ce que la farce soit sèche.","Laissez-la refroidir complètement : une farce tiède ramollit la pâte et le rouleau s'ouvre dans l'huile.","Préparez une pâte ferme à la farine et à la fécule et abaissez-la à deux millimètres — bien plus épais qu'une feuille de rouleau de printemps.","Roulez serré en repliant les deux bouts, et scellez à la pâte délayée.","Frites à 180 °C, six minutes. La pâte doit boursoufler et prendre une couleur ambrée uniforme."],
     en:["Cook the barley thirty minutes, chop the mutton and vegetables very finely, and simmer everything until the filling is dry.","Cool it completely: a warm filling softens the pastry and the roll opens in the oil.","Make a firm flour and cornflour dough and roll it to two millimetres — far thicker than a spring roll wrapper.","Roll tightly, folding both ends in, and seal with slaked flour.","Fry at 180°C for six minutes. The pastry should blister and take an even amber colour."]} },

{ id:'flat-white', c:'oc', lat:-37.818, lon:144.968, base:1, prep:10, cook:0, diff:2, tags:['drink','fast','breakfast'],
  art:{v:'glass',bg:'#33291f',plate:'#f4ead4',style:'drink',food:['#8f5a3a','#c9924a','#f2dfa8','#f4f0e6'],garnish:'#c9754a'},
  n:{fr:'Flat white',en:'Flat white'},
  p:{fr:'Melbourne, Victoria, Australie',en:'Melbourne, Victoria, Australia'},
  d:{fr:"Un espresso allongé de lait à micro-mousse très fine, sans couche de mousse sèche. L'Australie et la Nouvelle-Zélande s'en disputent l'invention depuis les années 1980 ; ce qui le distingue du latte n'est pas la quantité de lait mais la texture de la mousse, plus dense et plus brillante.",
     en:"An espresso lengthened with finely textured microfoam, with no dry foam layer. Australia and New Zealand have disputed its invention since the 1980s; what sets it apart from a latte is not the quantity of milk but the texture of the foam, denser and glossier."},
  i:[['coffee',20,'g'],['whole_milk',150,'ml']],
  s:{fr:["Extrayez un double ristretto de 40 ml en vingt-cinq secondes, sur une mouture fine et un tassage régulier.","Employez du lait entier bien froid : le froid laisse le temps de créer la mousse avant que le lait n'atteigne 65 °C.","Plongez la buse juste sous la surface pour introduire l'air trois secondes seulement, puis enfoncez-la pour faire tourner le lait.","Ce tourbillon casse les grosses bulles en micro-bulles : c'est là que se fait tout le flat white, et il ne se rattrape pas ensuite.","Arrêtez à 60-65 °C, tapez le pichet sur le plan et versez de haut puis de près, sans cuillère."],
     en:["Pull a 40 ml double ristretto in twenty-five seconds, on a fine grind and an even tamp.","Use cold whole milk: the cold gives time to build the foam before the milk reaches 65°C.","Set the wand just under the surface to introduce air for three seconds only, then submerge it to spin the milk.","That vortex breaks large bubbles into microbubbles: this is where the whole flat white is made, and it cannot be fixed afterwards.","Stop at 60-65°C, tap the jug on the bench and pour from high then close, with no spoon."]} },

{ id:'halal-snack-pack', c:'oc', lat:-37.981, lon:145.215, base:2, prep:30, cook:30, diff:2, tags:['lamb','street','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8c46a','#8f5a3a','#f4f0e6','#c9302a'],garnish:'#7fae6a'},
  n:{fr:'Halal snack pack',en:'Halal snack pack'},
  p:{fr:'Dandenong, Melbourne, Australie',en:'Dandenong, Melbourne, Australia'},
  d:{fr:"Une barquette de frites couverte de viande de kebab et de trois sauces. Née dans les kebaberies libanaises et turques des banlieues, elle a pris son nom en 2016 sur les réseaux sociaux ; les trois sauces — ail, piment, barbecue — sont canoniques.",
     en:"A tray of chips covered with kebab meat and three sauces. Born in the Lebanese and Turkish kebab shops of the suburbs, it took its name on social media in 2016; the three sauces — garlic, chilli, barbecue — are canonical."},
  i:[['lamb_shoulder',500,'g'],['potato',800,'g'],['cheddar_cheese',150,'g'],['garlic_sauce',100,'g'],['chili_sauce',80,'g'],['barbecue_sauce',80,'g'],['cumin',10,'g'],['paprika',10,'g'],['plain_yogurt',100,'g'],['frying_oil',2,'l'],['onion',1,'pc'],['salt',null,'']],
  s:{fr:["Faites mariner l'agneau tranché fin au yaourt, cumin et paprika, quatre heures au moins.","Le yaourt attendrit par ses enzymes et sa légère acidité, sans cuire la surface comme le ferait le citron.","Frites les pommes de terre deux fois : à 150 °C pour les cuire, puis à 190 °C pour les rendre croustillantes.","Grillez la viande à la plancha très chaude, en fine couche, jusqu'à ce que les bords caramélisent.","Montez dans la barquette : frites, fromage râpé qui fond au contact, viande, puis les trois sauces en filets croisés."],
     en:["Marinate the thinly sliced lamb in yoghurt, cumin and paprika, at least four hours.","Yoghurt tenderises through its enzymes and mild acidity, without cooking the surface as lemon would.","Fry the potatoes twice: at 150°C to cook them, then at 190°C to crisp them.","Grill the meat on a very hot plate in a thin layer, until the edges caramelise.","Build in the tray: chips, grated cheese that melts on contact, meat, then the three sauces in crossed lines."]} }
,

{ id:'vegemite-toast', c:'oc', lat:-37.820, lon:144.955, base:2, prep:5, cook:5, diff:1, tags:['breakfast','fast','bread'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#2b1a12','#e8c46a','#f2dfa8','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Tartine au Vegemite',en:'Vegemite toast'},
  p:{fr:'Melbourne, Victoria, Australie',en:'Melbourne, Victoria, Australia'},
  d:{fr:"Une tartine beurrée couverte d'une couche très fine de pâte de levure salée. Le Vegemite est né en 1922 des résidus de levure des brasseries de Melbourne ; l'erreur universelle des étrangers est d'en mettre l'épaisseur d'une confiture, alors qu'il en faut à peine une trace.",
     en:"Buttered toast under a very thin layer of salty yeast extract. Vegemite was born in 1922 from the yeast residue of Melbourne breweries; the universal foreign mistake is to spread it like jam, when barely a trace is wanted."},
  i:[['white_bread',4,'slice'],['butter',60,'g'],['yeast_extract',10,'g']],
  s:{fr:["Grillez le pain jusqu'à ce qu'il soit doré et encore chaud, jamais froid.","Beurrez généreusement pendant que le pain est brûlant, pour que le beurre fonde et pénètre.","Le beurre n'est pas facultatif : c'est le gras qui tempère le sel, et le Vegemite seul est immangeable pour la plupart.","Prélevez une quantité minuscule à la pointe du couteau et étalez-la en couche presque transparente.","On doit voir le pain au travers. Si la tartine est brune et opaque, il y en a dix fois trop."],
     en:["Toast the bread until golden and still hot, never cold.","Butter it generously while scalding, so the butter melts and soaks in.","The butter is not optional: the fat tempers the salt, and Vegemite alone is inedible to most people.","Take a tiny amount on the point of a knife and spread it almost transparently thin.","You should see the bread through it. If the toast is brown and opaque, there is ten times too much."]} },

{ id:'fairy-bread', c:'oc', lat:-37.810, lon:144.970, base:8, prep:10, cook:0, diff:1, tags:['sweet','fast','bread'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#f4f0e6','#e07a6a','#7fae5a','#e8c46a'],garnish:'#c9754a'},
  n:{fr:'Fairy bread',en:'Fairy bread'},
  p:{fr:'Melbourne, Victoria, Australie',en:'Melbourne, Victoria, Australia'},
  d:{fr:"Du pain de mie beurré couvert de petites billes de sucre colorées, coupé en triangles. C'est le gâteau d'anniversaire de toute enfance australienne depuis les années 1920 ; il n'y a pas de recette à proprement parler, seulement des règles absolues sur la découpe et l'épaisseur.",
     en:"Buttered white bread covered with coloured sugar sprinkles, cut into triangles. It has been the birthday staple of every Australian childhood since the 1920s; there is no recipe as such, only absolute rules about cutting and thickness."},
  i:[['white_bread',8,'slice'],['butter',120,'g'],['sprinkles',150,'g']],
  s:{fr:["Employez du pain de mie blanc très mou, jamais du pain complet ni du pain grillé.","Le beurre doit être à température ambiante et étalé jusqu'aux bords : une zone nue et les billes n'accrochent pas.","Versez les billes en pluie généreuse, puis pressez délicatement de la paume pour les faire adhérer.","Retirez les croûtes et coupez en deux diagonales, jamais en carrés ni en rectangles.","Les triangles sont la seule forme admise. Se sert immédiatement, le pain rassit très vite."],
     en:["Use very soft white sliced bread, never wholemeal and never toasted.","The butter must be at room temperature and spread right to the edges: one bare patch and the sprinkles will not stick.","Shower the sprinkles on generously, then press gently with your palm so they adhere.","Cut off the crusts and cut along both diagonals, never into squares or rectangles.","Triangles are the only permitted shape. Serve at once, the bread stales quickly."]} },

{ id:'vanilla-slice', c:'oc', lat:-34.185, lon:142.163, base:9, prep:60, cook:30, diff:3, tags:['sweet','bake','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#f2dfa8','#e8c46a','#f4f0e6','#e07a6a'],garnish:'#c9754a'},
  n:{fr:'Vanilla slice',en:'Vanilla slice'},
  p:{fr:'Mildura, Victoria, Australie',en:'Mildura, Victoria, Australia'},
  d:{fr:"Une crème pâtissière épaisse prise entre deux feuilles de pâte feuilletée, glacée au fruit de la passion. Mildura organise depuis 1998 un concours national de la meilleure vanilla slice ; on la surnomme snot block, ce qui n'a jamais nui à sa popularité.",
     en:"A thick custard set between two sheets of puff pastry, iced with passionfruit. Mildura has run a national best vanilla slice competition since 1998; it is nicknamed the snot block, which has never harmed its popularity."},
  i:[['puff_pastry',500,'g'],['whole_milk',1,'l'],['cornstarch',120,'g'],['egg_yolk',6,'pc'],['sugar',200,'g'],['butter',100,'g'],['vanilla',2,'pc'],['powdered_sugar',250,'g'],['passion_fruit',4,'pc'],['heavy_cream',200,'ml']],
  s:{fr:["Cuisez les deux abaisses de feuilletage entre deux plaques lestées : sans poids, elles gonflent et la crème ne tiendra pas.","Portez le lait à ébullition avec la vanille fendue, puis versez sur les jaunes battus au sucre et à la maïzena.","Remettez sur le feu et faites bouillir deux minutes pleines en fouettant : la maïzena n'épaissit qu'après ébullition franche.","Une crème retirée trop tôt paraît prise mais retombera en liquide en refroidissant, et le gâteau s'effondrera.","Coulez sur la première abaisse, couvrez de la seconde, réfrigérez six heures puis glacez au fruit de la passion."],
     en:["Bake both pastry sheets between two weighted trays: without weights they puff and the custard will not sit.","Bring the milk to the boil with the split vanilla, then pour it over the yolks beaten with sugar and cornflour.","Return to the heat and boil for two full minutes, whisking: cornflour thickens only after a proper boil.","A custard taken off too soon looks set but will slump back to liquid as it cools, and the slice will collapse.","Pour onto the first sheet, cover with the second, chill six hours then ice with passionfruit."]} },

{ id:'macadamia-crusted-fish', c:'oc', lat:-26.398, lon:153.093, base:4, prep:30, cook:20, diff:2, tags:['sea','bake','fresh'],
  art:{v:'plate',bg:'#26485c',plate:'#f0e4c8',style:'fish',food:['#f2dfa8','#f4f0e6','#e8c46a','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Poisson en croûte de macadamia',en:'Macadamia crusted fish'},
  p:{fr:'Noosa, Queensland, Australie',en:'Noosa, Queensland, Australia'},
  d:{fr:"Un filet de poisson blanc sous une croûte de noix de macadamia concassées. La macadamia est l'un des très rares aliments d'origine australienne cultivés commercialement dans le monde ; elle pousse à l'état sauvage dans les forêts du Queensland.",
     en:"A white fish fillet under a crust of crushed macadamias. The macadamia is one of very few Australian native foods grown commercially worldwide; it grows wild in the forests of Queensland."},
  i:[['white_fish',700,'g'],['macadamia_nuts',200,'g'],['breadcrumbs',80,'g'],['butter',80,'g'],['lemon',2,'pc'],['parsley',1,'bunch'],['dijon_mustard',30,'g'],['olive_oil',40,'ml'],['green_beans',300,'g'],['pepper',null,''],['salt',null,'']],
  s:{fr:["Concassez les macadamias au couteau, grossièrement : mixées, elles rendent leur huile et forment une pâte au lieu d'une croûte.","Mêlez-les à la chapelure, au beurre fondu, au persil et au zeste de citron.","Badigeonnez le poisson de moutarde : c'est elle qui fait tenir la croûte, il n'y a ni œuf ni farine.","Pressez la croûte sur le filet et enfournez à 200 °C pendant douze minutes seulement.","La macadamia est très grasse et brûle vite ; couvrez d'aluminium si elle colore avant que le poisson soit cuit."],
     en:["Crush the macadamias with a knife, roughly: blended, they release their oil and form a paste rather than a crust.","Mix them with the breadcrumbs, melted butter, parsley and lemon zest.","Brush the fish with mustard: that is what holds the crust on, there is no egg and no flour.","Press the crust onto the fillet and bake at 200°C for twelve minutes only.","Macadamia is very oily and burns fast; cover with foil if it colours before the fish is cooked."]} },

{ id:'bowen-mango-cheesecake', c:'oc', lat:-20.015, lon:148.245, base:10, prep:60, cook:0, diff:2, tags:['sweet','fruit','fresh'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#e8a032','#f4f0e6','#f2dfa8','#e8c46a'],garnish:'#c9754a'},
  n:{fr:'Cheesecake à la mangue de Bowen',en:'Bowen mango cheesecake'},
  p:{fr:'Bowen, Queensland, Australie',en:'Bowen, Queensland, Australia'},
  d:{fr:"Un cheesecake sans cuisson à la mangue Kensington Pride, dite mangue de Bowen. Cette variété est née d'un semis spontané dans les années 1880 à Bowen et représente aujourd'hui l'essentiel de la production australienne, sans que personne sache de quels parents elle vient.",
     en:"A no-bake cheesecake with Kensington Pride mango, known as the Bowen mango. The variety arose from a chance seedling at Bowen in the 1880s and now accounts for most of Australia's crop, with nobody knowing its parentage."},
  i:[['digestive_biscuits',250,'g'],['butter',120,'g'],['cream_cheese',600,'g'],['heavy_cream',400,'ml'],['powdered_sugar',150,'g'],['mango',3,'pc'],['gelatin',12,'g'],['lime',2,'pc'],['vanilla',1,'pc']],
  s:{fr:["Écrasez les biscuits au rouleau plutôt qu'au mixeur, pour garder une texture inégale, et liez au beurre fondu.","Tassez fermement et réfrigérez trente minutes avant de garnir : un fond mou s'effrite à la découpe.","Choisissez des mangues très mûres, à la peau tachetée de rouge et souples au toucher, et mixez-en deux en purée.","Faites gonfler la gélatine à l'eau froide puis dissolvez-la dans un peu de purée tiède, jamais bouillante — la chaleur la détruit.","Montez la crème séparément et incorporez-la à la spatule. Réfrigérez six heures et décorez de mangue fraîche en lamelles."],
     en:["Crush the biscuits with a rolling pin rather than a blender, to keep an uneven texture, and bind with melted butter.","Press firmly and chill thirty minutes before filling: a soft base crumbles when cut.","Choose very ripe mangoes, red-blushed and soft to the touch, and purée two of them.","Bloom the gelatine in cold water then dissolve it in a little warm purée, never boiling — heat destroys it.","Whip the cream separately and fold it in with a spatula. Chill six hours and decorate with sliced fresh mango."]} },

{ id:'pineapple-fritters', c:'oc', lat:-16.920, lon:145.771, base:6, prep:30, cook:20, diff:1, tags:['sweet','fry','fruit'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8c46a','#f2dfa8','#e8a032','#c9924a'],garnish:'#c9754a'},
  n:{fr:'Beignets d\'ananas',en:'Pineapple fritters'},
  p:{fr:'Cairns, Queensland, Australie',en:'Cairns, Queensland, Australia'},
  d:{fr:"Des rondelles d'ananas enrobées de pâte et frites, servies dans les friteries du Queensland. Elles se vendent au même comptoir que le poisson-frites, dans le même papier, et l'ananas du Queensland tropical y est assez acide pour supporter la pâte sucrée.",
     en:"Pineapple rings coated in batter and fried, sold in Queensland fish shops. They come from the same counter as fish and chips, in the same paper, and tropical Queensland pineapple is sharp enough to stand up to the sweet batter."},
  i:[['pineapple',1,'pc'],['flour',200,'g'],['baking_powder',8,'g'],['egg',2,'pc'],['whole_milk',250,'ml'],['sugar',60,'g'],['frying_oil',1.5,'l'],['cinnamon',5,'g'],['powdered_sugar',60,'g'],['salt',null,'']],
  s:{fr:["Coupez l'ananas en rondelles d'un centimètre et retirez le cœur ligneux à l'emporte-pièce.","Épongez chaque rondelle très soigneusement entre deux linges : l'ananas est gorgé de jus et la pâte glisse sur une surface mouillée.","Préparez une pâte assez épaisse pour napper le dos d'une cuillère, et laissez-la reposer vingt minutes.","Trempez et frites à 180 °C, deux minutes par face, sans surcharger le bain.","Saupoudrez de sucre glace à la cannelle et servez immédiatement — l'ananas rend son eau en refroidissant et ramollit la croûte."],
     en:["Cut the pineapple into one-centimetre rings and remove the woody core with a cutter.","Blot each ring very thoroughly between two cloths: pineapple is full of juice and batter slides off a wet surface.","Make a batter thick enough to coat the back of a spoon, and rest it twenty minutes.","Dip and fry at 180°C, two minutes a side, without crowding the oil.","Dust with cinnamon icing sugar and serve at once — pineapple weeps as it cools and softens the crust."]} },

{ id:'pie-floater', c:'oc', lat:-34.928, lon:138.600, base:4, prep:90, cook:60, diff:2, tags:['beef','soup','street'],
  art:{v:'bowl',bg:'#28331f',plate:'#f0e4c8',style:'soup',food:['#4f6f3a','#e8c46a','#8f5a3a','#c9302a'],garnish:'#7fae6a'},
  n:{fr:'Pie floater',en:'Pie floater'},
  p:{fr:'Victoria Square, Adélaïde, Australie',en:'Victoria Square, Adelaide, Australia'},
  d:{fr:"Une tourte à la viande retournée dans une soupe de pois cassés, nappée de sauce tomate. Elle se vendait dans les roulottes de nuit d'Adélaïde depuis les années 1890 ; l'Australie-Méridionale l'a classée icône culinaire de l'État en 2003.",
     en:"A meat pie upended in a pea soup and doused with tomato sauce. It was sold from Adelaide's night pie carts from the 1890s; South Australia declared it a State Heritage Icon in 2003."},
  i:[['ground_beef',600,'g'],['puff_pastry',400,'g'],['shortcrust_pastry',300,'g'],['split_peas',400,'g'],['onion',3,'pc'],['beef_stock',1.5,'l'],['flour',40,'g'],['worcestershire',30,'ml'],['ketchup',100,'g'],['mint',1,'bunch'],['bay_leaf',2,'pc'],['pepper',null,''],['salt',null,'']],
  s:{fr:["Faites tremper les pois cassés une nuit et cuisez-les deux heures avec le laurier, jusqu'à ce qu'ils se défassent complètement.","La soupe doit être épaisse au point que la tourte y flotte sans couler — c'est le sens du nom, et une soupe claire rate le plat.","Faites mijoter le bœuf haché avec l'oignon et le bouillon une heure, puis singez pour épaissir et laissez refroidir.","Foncez les moules de pâte brisée, garnissez froid et couvrez de feuilletage : brisée dessous pour tenir, feuilletée dessus pour gonfler.","Cuisez 30 minutes à 200 °C. Servez la tourte retournée, croûte vers le bas, dans la soupe, et versez le ketchup dessus."],
     en:["Soak the split peas overnight and cook them two hours with the bay, until completely collapsed.","The soup must be thick enough for the pie to float without sinking — that is the name, and a thin soup fails the dish.","Simmer the minced beef with onion and stock for an hour, then dust with flour to thicken and cool it.","Line the tins with shortcrust, fill cold and cover with puff: shortcrust below to hold, puff above to rise.","Bake 30 minutes at 200°C. Serve the pie inverted, crust down, in the soup, and pour the tomato sauce over."]} },

{ id:'frog-cake', c:'oc', lat:-34.921, lon:138.599, base:10, prep:120, cook:30, diff:3, tags:['sweet','bake','festive'],
  art:{v:'board',bg:'#28331f',plate:'#f4ead4',style:'cake',food:['#7fae5a','#f4f0e6','#f2dfa8','#e07a6a'],garnish:'#7fae6a'},
  n:{fr:'Frog cake',en:'Frog cake'},
  p:{fr:'Adélaïde, Australie-Méridionale, Australie',en:'Adelaide, South Australia, Australia'},
  d:{fr:"Un petit gâteau en forme de grenouille à la bouche ouverte, garni de crème et glacé au fondant. Créé à Adélaïde en 1922, il a été classé icône patrimoniale de l'Australie-Méridionale en 2001 ; la bouche ouverte est obtenue en fendant le sommet du gâteau en deux.",
     en:"A small cake shaped like an open-mouthed frog, filled with cream and iced with fondant. Created in Adelaide in 1922, it was listed as a South Australian heritage icon in 2001; the open mouth is made by splitting the top of the cake in two."},
  i:[['flour',250,'g'],['egg',5,'pc'],['sugar',200,'g'],['butter',150,'g'],['baking_powder',8,'g'],['heavy_cream',400,'ml'],['berry_jam',150,'g'],['fondant',600,'g'],['red_food_coloring',5,'ml'],['dark_chocolate',60,'g'],['vanilla',1,'pc']],
  s:{fr:["Cuisez une génoise ferme dans un moule profond, la veille, et laissez-la rassir : une génoise fraîche ne se sculpte pas.","Découpez des cylindres à l'emporte-pièce, puis arrondissez le sommet au couteau en forme de dôme.","Tranchez le dôme en biais aux deux tiers de sa hauteur sans détacher complètement : la partie supérieure devient la mâchoire.","Garnissez de confiture puis de crème fouettée ferme, en relevant la mâchoire pour ouvrir la bouche.","Trempez dans le fondant tiède coloré, en tenant par la base, et laissez prendre. Ajoutez les yeux au chocolat fondu."],
     en:["Bake a firm sponge in a deep tin the day before and let it stale: fresh sponge cannot be carved.","Cut cylinders with a ring cutter, then round the top with a knife into a dome.","Slice the dome on the bias two-thirds up without detaching it completely: the upper part becomes the jaw.","Fill with jam then firm whipped cream, lifting the jaw to open the mouth.","Dip in warm coloured fondant, holding by the base, and let it set. Add the eyes in melted chocolate."]} },

{ id:'kitchener-bun', c:'oc', lat:-34.930, lon:138.605, base:8, prep:180, cook:20, diff:2, tags:['sweet','fry','bake'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8c46a','#f4f0e6','#c9302a','#f2dfa8'],garnish:'#c9754a'},
  n:{fr:'Kitchener bun',en:'Kitchener bun'},
  p:{fr:'Adélaïde, Australie-Méridionale, Australie',en:'Adelaide, South Australia, Australia'},
  d:{fr:"Un beignet fendu sur le côté, garni de confiture et de crème fouettée. Il s'appelait Berliner jusqu'en 1915 ; l'Australie-Méridionale, largement peuplée d'Allemands, l'a rebaptisé du nom de Lord Kitchener pendant la Première Guerre mondiale, et le nom est resté.",
     en:"A doughnut split at the side, filled with jam and whipped cream. It was called a Berliner until 1915; South Australia, heavily German-settled, renamed it after Lord Kitchener during the First World War, and the name stuck."},
  i:[['flour',500,'g'],['fresh_yeast',20,'g'],['whole_milk',250,'ml'],['egg',3,'pc'],['butter',80,'g'],['sugar',80,'g'],['berry_jam',250,'g'],['heavy_cream',400,'ml'],['powdered_sugar',80,'g'],['frying_oil',2,'l'],['salt',null,'']],
  s:{fr:["Pétrissez une pâte briochée souple et laissez-la doubler, une heure et demie dans un endroit tiède.","Formez des boules, aplatissez-les légèrement et laissez pousser une seconde fois sur du papier fariné.","Manipulez-les par le papier au moment de frire : reprises à la main, elles se dégonflent et perdent leur anneau clair.","Frites à 170 °C, deux minutes par face. La ceinture pâle au milieu prouve que le beignet a bien flotté.","Fendez sur le côté sans traverser, garnissez de confiture puis de crème fouettée, et poudrez de sucre glace."],
     en:["Knead a soft enriched dough and let it double, an hour and a half somewhere warm.","Shape balls, flatten them slightly and prove a second time on floured paper.","Handle them by the paper when frying: picked up by hand they deflate and lose their pale ring.","Fry at 170°C, two minutes a side. The pale band around the middle proves the doughnut floated properly.","Split at the side without cutting through, fill with jam then whipped cream, and dust with icing sugar."]} },

{ id:'ab-yiros-pack', c:'oc', lat:-34.925, lon:138.601, base:2, prep:40, cook:30, diff:2, tags:['lamb','street','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#e8c46a','#8f5a3a','#f4f0e6','#c9302a'],garnish:'#7fae6a'},
  n:{fr:'AB',en:'AB'},
  p:{fr:'Adélaïde, Australie-Méridionale, Australie',en:'Adelaide, South Australia, Australia'},
  d:{fr:"Des frites couvertes de viande de yiros, de sauces et de sel de poulet, spécialité d'Adélaïde. Le sigle vient de « atomic bomb », créé au Blue and White Café dans les années 1960 ; c'est l'ancêtre direct du halal snack pack de Melbourne, de vingt ans son aîné.",
     en:"Chips covered with yiros meat, sauces and chicken salt, an Adelaide speciality. The initials stand for atomic bomb, coined at the Blue and White Café in the 1960s; it is the direct ancestor of Melbourne's halal snack pack, by twenty years."},
  i:[['lamb_shoulder',400,'g'],['potato',800,'g'],['garlic_sauce',100,'g'],['chili_sauce',60,'g'],['barbecue_sauce',60,'g'],['chicken_salt',20,'g'],['plain_yogurt',100,'g'],['oregano',5,'g'],['cumin',8,'g'],['frying_oil',2,'l'],['onion',1,'pc']],
  s:{fr:["Faites mariner l'agneau au yaourt, à l'origan et au cumin, quatre heures, puis grillez-le en fine couche à la plancha.","Coupez les pommes de terre en bâtonnets épais et faites-les tremper une heure à l'eau froide pour ôter l'amidon de surface.","Ce trempage empêche les frites de coller entre elles, ce qui compte quand elles sont noyées de sauce.","Frites deux fois, à 150 °C puis à 190 °C, et salez au sel de poulet dès la sortie du bain.","Montez frites, viande, puis les trois sauces. Se mange à la fourchette en plastique, directement dans la barquette."],
     en:["Marinate the lamb in yoghurt, oregano and cumin for four hours, then grill it in a thin layer on a hot plate.","Cut the potatoes into thick chips and soak them an hour in cold water to remove surface starch.","That soaking stops the chips sticking together, which matters when they are drowned in sauce.","Fry twice, at 150°C then 190°C, and season with chicken salt straight out of the oil.","Build chips, meat, then the three sauces. Eaten with a plastic fork, straight from the tray."]} },

{ id:'lamb-chops-bbq', c:'oc', lat:-31.953, lon:115.861, base:6, prep:120, cook:20, diff:1, tags:['lamb','grill','fast'],
  art:{v:'board',bg:'#2b2419',plate:'#f4ead4',style:'grill',food:['#8f4a3a','#5a3020','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Côtelettes d\'agneau au barbecue',en:'Barbecue lamb chops'},
  p:{fr:'Perth, Australie-Occidentale, Australie',en:'Perth, Western Australia, Australia'},
  d:{fr:"Des côtelettes d'agneau grillées au barbecue, marinées au romarin et à l'ail. L'agneau australien est nourri à l'herbe toute l'année : sa graisse est plus jaune et son goût plus prononcé que celui des agneaux de bergerie européens.",
     en:"Lamb chops grilled on the barbecue, marinated with rosemary and garlic. Australian lamb is grass-fed year round: its fat is yellower and its flavour stronger than that of European shed-raised lamb."},
  i:[['lamb_chops',12,'pc'],['rosemary',2,'bunch'],['garlic',8,'clove'],['olive_oil',100,'ml'],['lemon',2,'pc'],['coarse_salt',20,'g'],['black_peppercorns',10,'g'],['potato',800,'g'],['cabbage',300,'g'],['mayonnaise',150,'g']],
  s:{fr:["Sortez les côtelettes une heure avant : une viande froide au centre grille de l'extérieur et reste crue au cœur.","Faites-les mariner à l'huile, au romarin et à l'ail, mais salez seulement au moment de poser sur la grille.","Le sel dans la marinade tire l'humidité et la viande bout dans son propre jus au lieu de saisir.","Grillez à feu vif trois minutes par face, en tenant les côtelettes debout sur le gras trente secondes pour le faire fondre.","Laissez reposer cinq minutes sous un papier avant de servir, avec citron et salade de chou."],
     en:["Take the chops out an hour ahead: meat cold at the centre chars outside and stays raw within.","Marinate them in oil, rosemary and garlic, but salt only as they go on the grill.","Salt in the marinade draws out moisture and the meat boils in its own juices instead of searing.","Grill over high heat three minutes a side, standing the chops on their fat edge for thirty seconds to render it.","Rest five minutes under paper before serving, with lemon and coleslaw."]} }
,

{ id:'tasmanian-scallop-pie', c:'oc', lat:-42.033, lon:147.489, base:6, prep:90, cook:40, diff:3, tags:['sea','bake','comfort'],
  art:{v:'plate',bg:'#26485c',plate:'#f4ead4',style:'pastry',food:['#e8c46a','#e8a032','#f4f0e6','#f2dfa8'],garnish:'#6fbf8f'},
  n:{fr:'Tourte aux pétoncles de Tasmanie',en:'Tasmanian scallop pie'},
  p:{fr:'Ross, Tasmanie, Australie',en:'Ross, Tasmania, Australia'},
  d:{fr:"Une tourte individuelle aux pétoncles dans une sauce jaune au curry. La couleur vive vient du curry, ajouté au XIXe siècle par les colons britanniques ; le pétoncle de Tasmanie a une chair plus dense que celle des eaux chaudes, et supporte la cuisson en croûte.",
     en:"An individual pie of scallops in a yellow curry sauce. The bright colour comes from curry powder, added by British settlers in the nineteenth century; the Tasmanian scallop has denser flesh than warm-water kinds and stands up to baking in pastry."},
  i:[['scallops',600,'g'],['shortcrust_pastry',400,'g'],['puff_pastry',300,'g'],['onion',2,'pc'],['butter',80,'g'],['flour',60,'g'],['whole_milk',400,'ml'],['curry_powder',20,'g'],['smoked_bacon',100,'g'],['parsley',1,'bunch'],['egg',1,'pc'],['pepper',null,''],['salt',null,'']],
  s:{fr:["Retirez le muscle latéral des pétoncles, ce petit rectangle plus ferme qui reste caoutchouteux quelle que soit la cuisson.","Ne les faites pas cuire à l'avance : ils rendent leur eau et deviennent secs, alors qu'ils cuisent en huit minutes dans la tourte.","Préparez une béchamel épaisse au curry, en faisant griller la poudre trente secondes dans le beurre avant d'ajouter la farine.","Laissez la sauce refroidir complètement avant d'y mêler les pétoncles crus et de garnir les moules.","Foncez de pâte brisée, couvrez de feuilletage, dorez et cuisez 30 minutes à 200 °C."],
     en:["Remove the side muscle from the scallops, that small firmer rectangle that stays rubbery however it is cooked.","Do not cook them in advance: they weep and go dry, whereas they cook in eight minutes inside the pie.","Make a thick curried béchamel, toasting the powder thirty seconds in the butter before adding the flour.","Cool the sauce completely before folding in the raw scallops and filling the tins.","Line with shortcrust, cover with puff, glaze and bake 30 minutes at 200°C."]} },

{ id:'tasmanian-apple-pie', c:'oc', lat:-43.030, lon:147.048, base:8, prep:90, cook:55, diff:2, tags:['sweet','bake','fruit'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e8c46a','#f2dfa8','#f4f0e6','#c9754a'],garnish:'#c9754a'},
  n:{fr:'Tourte aux pommes de Tasmanie',en:'Tasmanian apple pie'},
  p:{fr:'Huonville, Tasmanie, Australie',en:'Huonville, Tasmania, Australia'},
  d:{fr:"Une tourte double croûte aux pommes de la vallée du Huon, à la cannelle. La Tasmanie était surnommée l'Apple Isle : elle exportait quelque cinq millions de caisses par an vers l'Europe jusqu'à ce que l'adhésion britannique au Marché commun, en 1973, ferme le débouché.",
     en:"A double-crust pie of Huon valley apples with cinnamon. Tasmania was nicknamed the Apple Isle: it shipped some five million cases a year to Europe until Britain's entry into the Common Market in 1973 closed the trade."},
  i:[['apple',1.2,'kg'],['flour',400,'g'],['butter',250,'g'],['sugar',180,'g'],['cinnamon',10,'g'],['lemon',1,'pc'],['cornstarch',30,'g'],['egg',1,'pc'],['heavy_cream',200,'ml'],['nutmeg',3,'g'],['salt',null,'']],
  s:{fr:["Mêlez deux variétés : une acide qui se défait et une ferme qui tient, sans quoi la garniture est uniforme et plate.","Faites macérer les pommes tranchées avec le sucre trente minutes, puis récupérez le jus rendu et faites-le réduire à part.","Ce jus réduit et remis dans la tourte concentre le goût ; laissé tel quel, il détremperait la pâte du fond.","Liez à la maïzena et laissez refroidir avant de garnir la tourte foncée de pâte brisée.","Couvrez, soudez, incisez trois fois et cuisez 55 minutes à 190 °C. Laissez refroidir deux heures avant de couper."],
     en:["Mix two varieties: a sharp one that collapses and a firm one that holds, or the filling is uniform and dull.","Macerate the sliced apples with the sugar for thirty minutes, then draw off the released juice and reduce it separately.","That reduced juice put back into the pie concentrates the flavour; left as it was, it would soak the base.","Thicken with cornflour and cool before filling the shortcrust-lined tin.","Cover, seal, cut three vents and bake 55 minutes at 190°C. Cool two hours before cutting."]} },

{ id:'leatherwood-honey-ice-cream', c:'oc', lat:-41.435, lon:145.913, base:8, prep:40, cook:20, diff:2, tags:['sweet','fresh','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ead4',style:'other',food:['#f2dfa8','#e8c46a','#f4f0e6','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Glace au miel de leatherwood',en:'Leatherwood honey ice cream'},
  p:{fr:'Nord-ouest de la Tasmanie, Australie',en:'North-west Tasmania, Australia'},
  d:{fr:"Une crème glacée au miel de leatherwood, arbre endémique des forêts pluviales de Tasmanie. Ce miel très parfumé, presque floral et légèrement poivré, ne se produit nulle part ailleurs au monde ; l'arbre met cent ans à fleurir abondamment.",
     en:"An ice cream made with leatherwood honey, from a tree endemic to Tasmania's rainforests. This intensely perfumed honey, almost floral and faintly peppery, is produced nowhere else on earth; the tree takes a century to flower abundantly."},
  i:[['whole_milk',500,'ml'],['heavy_cream',500,'ml'],['honey',250,'g'],['egg_yolk',6,'pc'],['sugar',60,'g'],['vanilla',1,'pc'],['salt',null,'']],
  s:{fr:["Chauffez le lait et la crème avec la vanille sans faire bouillir, puis versez sur les jaunes battus au sucre.","Faites cuire à la nappe, à 82 °C exactement : au-delà de 85 °C les jaunes coagulent et la crème devient granuleuse.","Retirez du feu et incorporez le miel hors du feu, en fouettant — chauffé, il perd ses arômes volatils, qui sont tout son intérêt.","Passez au chinois, refroidissez rapidement dans un bain d'eau glacée et laissez maturer douze heures au réfrigérateur.","Turbinez. Le miel abaisse le point de congélation : cette glace reste souple et se sert directement à la sortie du congélateur."],
     en:["Heat the milk and cream with the vanilla without boiling, then pour onto the yolks beaten with sugar.","Cook to the nappe at exactly 82°C: beyond 85°C the yolks coagulate and the custard turns grainy.","Off the heat, whisk in the honey — heated, it loses the volatile aromas that are its whole point.","Strain, cool rapidly over iced water and mature twelve hours in the refrigerator.","Churn. Honey lowers the freezing point: this ice cream stays soft and can be served straight from the freezer."]} },

{ id:'pepperberry-wallaby', c:'oc', lat:-41.435, lon:147.137, base:4, prep:60, cook:20, diff:3, tags:['grill','fresh','festive'],
  art:{v:'plate',bg:'#2b2419',plate:'#f0e4c8',style:'grill',food:['#5a2a2a','#8f4a3a','#3a2a2a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Wallaby au poivre de Tasmanie',en:'Pepperberry wallaby'},
  p:{fr:'Launceston, Tasmanie, Australie',en:'Launceston, Tasmania, Australia'},
  d:{fr:"Du filet de wallaby saisi, croûté au poivre de montagne de Tasmanie. La baie de Tasmannia lanceolata mord d'abord doucement puis engourdit la langue trente secondes plus tard : elle demande une main légère, contrairement au poivre noir.",
     en:"Seared wallaby fillet crusted with Tasmanian mountain pepper. The berry of Tasmannia lanceolata bites gently at first then numbs the tongue thirty seconds later: it needs a light hand, unlike black pepper."},
  i:[['wallaby',600,'g'],['pepperberry',15,'g'],['butter',80,'g'],['red_wine',200,'ml'],['beef_stock',300,'ml'],['sweet_potato',600,'g'],['thyme',1,'bunch'],['garlic',4,'clove'],['olive_oil',40,'ml'],['salt',null,'']],
  s:{fr:["Le wallaby est une viande extrêmement maigre : elle ne supporte aucune cuisson au-delà du saignant, et durcit brutalement à point.","Concassez les baies grossièrement et n'en mettez que la moitié de ce que vous mettriez de poivre noir.","Saisissez le filet deux minutes par face dans une poêle brûlante, puis retirez-le du feu.","Laissez reposer aussi longtemps que la cuisson, sous un papier, dans un endroit tiède.","Déglacez au vin rouge, réduisez avec le bouillon et montez au beurre froid hors du feu. Servez avec une purée de patate douce."],
     en:["Wallaby is extremely lean meat: it takes no cooking beyond rare, and toughens abruptly at medium.","Crush the berries roughly and use half what you would of black pepper.","Sear the fillet two minutes a side in a scalding pan, then take it off the heat.","Rest it as long as it cooked, under paper, somewhere warm.","Deglaze with red wine, reduce with the stock and mount with cold butter off the heat. Serve with sweet potato mash."]} },

{ id:'kangaroo-steak', c:'oc', lat:-23.698, lon:133.881, base:4, prep:120, cook:15, diff:2, tags:['grill','fresh','fast'],
  art:{v:'plate',bg:'#2b2419',plate:'#f0e4c8',style:'grill',food:['#5a2a2a','#8f4a3a','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Steak de kangourou',en:'Kangaroo steak'},
  p:{fr:'Alice Springs, Territoire du Nord, Australie',en:'Alice Springs, Northern Territory, Australia'},
  d:{fr:"Un filet de kangourou saisi saignant, servi avec une sauce à la prune kakadu. La viande contient moins de 2 % de gras et beaucoup de fer : elle ne se cuit jamais au-delà du saignant, et l'Australie est le seul pays au monde à en réguler la chasse commerciale.",
     en:"Kangaroo fillet seared rare, served with a Kakadu plum sauce. The meat is under 2% fat and rich in iron: it is never cooked beyond rare, and Australia is the only country in the world to regulate its commercial harvest."},
  i:[['kangaroo',600,'g'],['olive_oil',60,'ml'],['garlic',4,'clove'],['rosemary',1,'bunch'],['red_wine',200,'ml'],['bush_plum',80,'g'],['beef_stock',300,'ml'],['butter',60,'g'],['sweet_potato',600,'g'],['pepper',null,''],['salt',null,'']],
  s:{fr:["Sortez la viande une heure avant et laissez-la revenir à température ambiante, sans marinade acide.","Le kangourou n'a presque pas de gras : la marinade au citron ou au vinaigre le durcit au lieu de l'attendrir, contrairement au bœuf.","Huilez la viande et non la poêle, et saisissez à feu maximal deux minutes par face, pas davantage.","Le cœur doit rester franchement rouge. À point, la viande devient sèche et prend un goût de foie prononcé.","Laissez reposer dix minutes, tranchez en travers de la fibre et nappez d'une sauce au vin rouge et à la prune kakadu."],
     en:["Take the meat out an hour ahead and let it come to room temperature, with no acid marinade.","Kangaroo has almost no fat: a lemon or vinegar marinade toughens it rather than tenderising, unlike beef.","Oil the meat rather than the pan, and sear over maximum heat two minutes a side, no longer.","The centre must stay frankly red. At medium the meat goes dry and takes on a pronounced liver taste.","Rest ten minutes, slice across the grain and coat with a red wine and Kakadu plum sauce."]} },

{ id:'crocodile-curry', c:'oc', lat:-12.463, lon:130.846, base:6, prep:60, cook:60, diff:2, tags:['stew','spicy','comfort'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'stew',food:['#e8a032','#f4f0e6','#e8c46a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Curry de crocodile',en:'Crocodile curry'},
  p:{fr:'Darwin, Territoire du Nord, Australie',en:'Darwin, Northern Territory, Australia'},
  d:{fr:"Un curry au lait de coco à base de queue de crocodile marin, élevé dans les fermes du Top End. La chair de queue est blanche, ferme et proche du poulet ; le reste de l'animal est plus foncé et bien plus coriace, et n'entre pas dans ce plat.",
     en:"A coconut curry made with saltwater crocodile tail, farmed in the Top End. Tail meat is white, firm and close to chicken; the rest of the animal is darker and far tougher, and has no place in this dish."},
  i:[['crocodile',800,'g'],['coconut_milk',600,'ml'],['curry_paste',80,'g'],['onion',2,'pc'],['garlic',6,'clove'],['ginger',40,'g'],['lemongrass',2,'stalk'],['lime',3,'pc'],['cilantro',1,'bunch'],['long_grain_rice',400,'g'],['fish_sauce',30,'ml'],['sunflower_oil',60,'ml']],
  s:{fr:["N'employez que la chair de queue, coupée en cubes de trois centimètres, en retirant tout le cartilage.","Faites-la revenir très brièvement, une minute par face : elle est maigre et durcit exactement comme le blanc de poulet.","Faites griller la pâte de curry dans l'huile chaude jusqu'à ce qu'elle se sépare et que l'huile se colore.","Ajoutez le lait de coco par petites quantités en remuant, pour qu'il émulsionne au lieu de trancher.","Remettez la viande pour les quinze dernières minutes seulement, à frémissement. Citron vert hors du feu."],
     en:["Use tail meat only, cut into three-centimetre cubes, with all cartilage removed.","Sear it very briefly, a minute a side: it is lean and toughens exactly like chicken breast.","Fry the curry paste in hot oil until it splits and the oil takes colour.","Add the coconut milk in small additions, stirring, so it emulsifies rather than splitting.","Return the meat for the last fifteen minutes only, at a tremble. Lime off the heat."]} },

{ id:'witchetty-grubs', c:'oc', lat:-22.243, lon:134.220, base:4, prep:15, cook:10, diff:1, tags:['grill','fresh','fast'],
  art:{v:'board',bg:'#2b2419',plate:'#f4ead4',style:'other',food:['#f2dfa8','#e8dcb8','#c9924a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Larves witchetty',en:'Witchetty grubs'},
  p:{fr:'Utopia, Territoire du Nord, Australie',en:'Utopia, Northern Territory, Australia'},
  d:{fr:"De grosses larves de coléoptère grillées sur la braise, aliment aborigène du désert central. Elles sont extraites des racines de l'acacia witchetty et fournissent un apport très dense en protéines et en lipides : quelques larves suffisent à un repas.",
     en:"Large beetle larvae grilled on the coals, an Aboriginal food of the central desert. They are dug from the roots of the witchetty bush and are extremely dense in protein and fat: a few grubs make a meal."},
  i:[['witchetty_grubs',400,'g'],['coarse_salt',10,'g']],
  s:{fr:["Ne les lavez pas à l'eau : elles se percent et perdent leur contenu, qui est l'essentiel de leur substance.","Essuyez-les simplement à la main et retirez la tête sombre d'une pression.","Posez-les directement sur des cendres chaudes plutôt que sur des braises vives, qui les feraient éclater.","Trois à quatre minutes suffisent : la peau se raffermit et prend une couleur dorée, l'intérieur reste crémeux.","Se mangent entières, sans assaisonnement. Crues, elles sont également consommées et ont un goût d'amande."],
     en:["Do not wash them in water: they puncture and lose their contents, which are the substance of them.","Simply wipe them by hand and pinch off the dark head.","Set them directly on hot ashes rather than live coals, which would burst them.","Three or four minutes is enough: the skin firms and turns golden, the inside stays creamy.","Eaten whole, unseasoned. They are also eaten raw, and taste of almond."]} },

{ id:'quandong-pie', c:'oc', lat:-23.702, lon:133.878, base:8, prep:90, cook:50, diff:2, tags:['sweet','bake','fruit'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#c9302a','#e8c46a','#f2dfa8','#f4f0e6'],garnish:'#c9754a'},
  n:{fr:'Tourte au quandong',en:'Quandong pie'},
  p:{fr:'Alice Springs, Territoire du Nord, Australie',en:'Alice Springs, Northern Territory, Australia'},
  d:{fr:"Une tourte au quandong, pêche du désert d'un rouge vif et franchement acide. L'arbre est un hémiparasite : il puise une part de sa sève dans les racines des plantes voisines, ce qui rend sa culture difficile et le fruit longtemps resté sauvage.",
     en:"A pie of quandong, the bright red and frankly sour desert peach. The tree is a hemiparasite: it draws part of its sap from neighbouring plants' roots, which makes cultivation difficult and long kept the fruit wild."},
  i:[['quandong',600,'g'],['flour',400,'g'],['butter',250,'g'],['sugar',250,'g'],['cornstarch',40,'g'],['egg',1,'pc'],['lemon',1,'pc'],['cinnamon',5,'g'],['heavy_cream',200,'ml'],['salt',null,'']],
  s:{fr:["Employez des quandongs séchés réhydratés ou frais dénoyautés ; le noyau est très gros et occupe la moitié du fruit.","Faites-les compoter avec le sucre vingt minutes : le fruit est bien plus acide qu'une pomme et demande presque le double de sucre.","Goûtez avant de sucrer davantage — l'acidité varie fortement d'un arbre à l'autre.","Liez à la maïzena et laissez refroidir complètement avant de garnir la tourte.","Couvrez, dorez à l'œuf et cuisez 45 minutes à 190 °C. Servez tiède avec de la crème."],
     en:["Use dried rehydrated quandongs or fresh stoned ones; the stone is very large and takes up half the fruit.","Stew them with the sugar for twenty minutes: the fruit is far sharper than apple and needs almost twice the sugar.","Taste before adding more sugar — the acidity varies greatly from tree to tree.","Thicken with cornflour and cool completely before filling the pie.","Cover, glaze with egg and bake 45 minutes at 190°C. Serve warm with cream."]} },

{ id:'green-ant-barramundi', c:'oc', lat:-12.752, lon:134.223, base:4, prep:40, cook:20, diff:2, tags:['sea','grill','fresh'],
  art:{v:'leaf',bg:'#28331f',plate:'#f0e4c8',style:'fish',food:['#f4f0e6','#7fae5a','#e8c46a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Barramundi aux fourmis vertes',en:'Green ant barramundi'},
  p:{fr:'Terre d\'Arnhem, Territoire du Nord, Australie',en:'Arnhem Land, Northern Territory, Australia'},
  d:{fr:"Du barramundi cuit en feuille de paperbark, assaisonné de fourmis vertes écrasées. L'abdomen de la fourmi tisserande contient de l'acide formique, d'un goût de citron vert très net : elle remplace l'agrume dans une région où il n'en pousse pas.",
     en:"Barramundi cooked in paperbark, seasoned with crushed green ants. The weaver ant's abdomen holds formic acid with a sharp lime flavour: it replaces citrus in a region where none grows."},
  i:[['barramundi',800,'g'],['green_ants',30,'g'],['paperbark',6,'pc'],['lemon_myrtle',5,'g'],['bush_tomato',80,'g'],['olive_oil',40,'ml'],['sweet_potato',500,'g'],['salt',null,'']],
  s:{fr:["Faites tremper l'écorce de paperbark une heure dans l'eau : sèche, elle brûle immédiatement sur la braise.","Écrasez les fourmis vertes au mortier juste avant l'emploi ; leur acidité s'évente en quelques heures.","N'ajoutez pas de citron : les deux acidités se contrarient, et la fourmi seule suffit largement.","Enveloppez le poisson entier dans deux couches d'écorce, ficelez et posez sur des braises modérées.","Douze minutes par face. L'écorce noircit dehors et le poisson cuit à la vapeur de sa propre humidité."],
     en:["Soak the paperbark an hour in water: dry, it burns immediately on the coals.","Crush the green ants in a mortar just before use; their acidity fades within hours.","Add no lemon: the two acidities fight each other, and the ants alone are more than enough.","Wrap the whole fish in two layers of bark, tie and set on moderate coals.","Twelve minutes a side. The bark blackens outside while the fish steams in its own moisture."]} },

{ id:'lemon-myrtle-chicken', c:'oc', lat:-12.847, lon:132.813, base:4, prep:60, cook:40, diff:2, tags:['poultry','grill','fresh'],
  art:{v:'plate',bg:'#28331f',plate:'#f0e4c8',style:'grill',food:['#c9924a','#e8c46a','#7fae5a','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Poulet au myrte citronné',en:'Lemon myrtle chicken'},
  p:{fr:'Kakadu, Territoire du Nord, Australie',en:'Kakadu, Northern Territory, Australia'},
  d:{fr:"Du poulet mariné au myrte citronné, plante indigène du Queensland. Sa feuille contient jusqu'à 95 % de citral, la molécule qui donne son parfum au citron : c'est la concentration la plus élevée connue dans le règne végétal, bien au-dessus de la citronnelle.",
     en:"Chicken marinated in lemon myrtle, a Queensland native. Its leaf holds up to 95% citral, the molecule that gives lemon its scent: the highest concentration known in the plant kingdom, far above lemongrass."},
  i:[['chicken',1.4,'kg'],['lemon_myrtle',15,'g'],['plain_yogurt',200,'g'],['garlic',6,'clove'],['olive_oil',60,'ml'],['honey',40,'g'],['sweet_potato',600,'g'],['macadamia_nuts',80,'g'],['pepper',null,''],['salt',null,'']],
  s:{fr:["Employez le myrte citronné avec parcimonie : à cette concentration en citral, une cuillerée suffit pour un poulet entier.","Trop dosé, il devient franchement médicinal et domine tout le plat — c'est l'erreur des cuisiniers qui le découvrent.","Faites mariner le poulet deux heures au yaourt, à l'ail, au miel et au myrte moulu.","Rôtissez à 190 °C pendant quarante minutes, en arrosant deux fois du jus rendu.","Parsemez de myrte frais moulu à la sortie du four, hors cuisson : c'est là que le parfum est le plus vif."],
     en:["Use lemon myrtle sparingly: at that citral concentration, a spoonful is enough for a whole chicken.","Overdone, it turns frankly medicinal and dominates everything — the mistake of cooks meeting it for the first time.","Marinate the chicken two hours in yoghurt, garlic, honey and ground myrtle.","Roast at 190°C for forty minutes, basting twice with the released juices.","Scatter freshly ground myrtle over as it leaves the oven, off the heat: that is when the scent is sharpest."]} },

{ id:'canberra-truffle-pie', c:'oc', lat:-35.256, lon:149.437, base:6, prep:90, cook:50, diff:3, tags:['beef','bake','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#3a2a2a','#e8c46a','#f2dfa8','#8f5a3a'],garnish:'#7fae6a'},
  n:{fr:'Tourte à la truffe de Canberra',en:'Canberra truffle pie'},
  p:{fr:'Bungendore, Territoire de la capitale, Australie',en:'Bungendore, Australian Capital Territory, Australia'},
  d:{fr:"Une tourte au bœuf braisé parfumée à la truffe noire de la région de Canberra. L'Australie récolte sa truffe du Périgord en juin et juillet, à contre-saison de l'hémisphère nord : elle approvisionne l'Europe en plein été, quand la sienne n'existe pas.",
     en:"A braised beef pie scented with black truffle from the Canberra district. Australia harvests its Périgord truffle in June and July, opposite to the northern hemisphere: it supplies Europe in high summer, when none of its own exists."},
  i:[['beef_cheek',1,'kg'],['black_truffle',20,'g'],['shortcrust_pastry',400,'g'],['puff_pastry',300,'g'],['red_wine',400,'ml'],['beef_stock',600,'ml'],['onion',2,'pc'],['carrot',2,'pc'],['flour',40,'g'],['butter',80,'g'],['thyme',1,'bunch'],['egg',1,'pc'],['salt',null,'']],
  s:{fr:["Braisez les joues de bœuf trois heures au vin rouge, jusqu'à ce qu'elles se défassent à la cuillère.","Laissez refroidir la garniture une nuit entière avant d'ajouter la truffe.","La truffe ne se cuit pas : ses arômes sont volatils et une heure de four les efface entièrement.","Râpez-la dans la garniture froide, mêlez et laissez infuser deux heures au réfrigérateur, couvert.","Garnissez les tourtes, couvrez de feuilletage et cuisez 30 minutes à 200 °C. Râpez encore un peu de truffe à l'ouverture."],
     en:["Braise the beef cheeks three hours in red wine, until they fall apart under a spoon.","Cool the filling overnight before adding the truffle.","Truffle is not cooked: its aromas are volatile and an hour in the oven erases them entirely.","Grate it into the cold filling, mix and infuse two hours in the refrigerator, covered.","Fill the pies, cover with puff pastry and bake 30 minutes at 200°C. Grate a little more truffle as they are opened."]} }
];
